"""Protocol tests use generated byte fixtures only; no audio is classified."""

from io import BytesIO
import struct
import unittest
import wave
import zlib

from tools.soniq_serial_audio_companion import (
    CHANNELS,
    DATA,
    END,
    END_META,
    PCM16LE,
    SAMPLE_RATE_HZ,
    START,
    START_META,
    CaptureAssembler,
    ProtocolError,
    cobs_decode,
    cobs_encode,
    encode_record,
    pcm_to_wav,
)


CAPTURE_ID = bytes.fromhex("00112233445566778899aabbccddeeff")


def protocol_fixture(*, wrong_capture_crc=False):
    """Construct protocol-only bytes; payload has no sensor or label meaning."""
    pcm = bytes(index % 251 for index in range(16_000 * 2))
    records = [encode_record(START, CAPTURE_ID, 0,
                             START_META.pack(SAMPLE_RATE_HZ, CHANNELS, PCM16LE, 16_000))]
    chunks = [pcm[index:index + 1000] for index in range(0, len(pcm), 1000)]
    for sequence, chunk in enumerate(chunks, 1):
        records.append(encode_record(DATA, CAPTURE_ID, sequence, chunk))
    whole_crc = zlib.crc32(pcm) & 0xFFFFFFFF
    if wrong_capture_crc:
        whole_crc ^= 1
    records.append(encode_record(END, CAPTURE_ID, len(chunks) + 1,
                                 END_META.pack(len(chunks), 16_000, whole_crc)))
    return pcm, records


class CobsTests(unittest.TestCase):
    def test_round_trip_with_zeroes_and_long_nonzero_runs(self):
        value = bytes(range(256)) * 3
        self.assertEqual(cobs_decode(cobs_encode(value)), value)


class CaptureAssemblerTests(unittest.TestCase):
    def test_assembles_only_complete_crc_verified_capture_across_fragments(self):
        pcm, records = protocol_fixture()
        assembler = CaptureAssembler()
        wire = b"".join(records)
        results = []
        for offset in range(0, len(wire), 137):
            results.extend(assembler.feed(wire[offset:offset + 137], now=1.0))
        self.assertEqual(len(results), 1)
        self.assertEqual(results[0].capture_id, CAPTURE_ID)
        self.assertEqual(results[0].pcm16le, pcm)

    def test_out_of_order_sequence_discards_capture(self):
        _, records = protocol_fixture()
        assembler = CaptureAssembler()
        assembler.feed(records[0], now=1.0)
        with self.assertRaisesRegex(ProtocolError, "sequence"):
            assembler.feed(records[2], now=1.1)
        self.assertIsNone(assembler._active)

    def test_corrupt_frame_crc_is_rejected(self):
        _, records = protocol_fixture()
        corrupted = bytearray(records[0])
        corrupted[-3] ^= 1
        with self.assertRaises(ProtocolError):
            CaptureAssembler().feed(bytes(corrupted), now=1.0)

    def test_valid_capture_can_start_after_corrupt_delimited_record(self):
        pcm, records = protocol_fixture()
        bad = bytearray(records[0])
        bad[-3] ^= 1
        assembler = CaptureAssembler()
        with self.assertRaises(ProtocolError):
            assembler.feed(bytes(bad), now=1.0)
        results = []
        for record in records:
            results.extend(assembler.feed(record, now=1.1))
        self.assertEqual(len(results), 1)
        self.assertEqual(results[0].pcm16le, pcm)

    def test_wrong_whole_capture_crc_is_rejected(self):
        _, records = protocol_fixture(wrong_capture_crc=True)
        assembler = CaptureAssembler()
        for frame in records[:-1]:
            assembler.feed(frame, now=1.0)
        with self.assertRaisesRegex(ProtocolError, "whole-capture CRC"):
            assembler.feed(records[-1], now=1.0)

    def test_capture_timeout_discards_partial_transfer(self):
        _, records = protocol_fixture()
        assembler = CaptureAssembler(capture_timeout=10.0)
        assembler.feed(records[0], now=1.0)
        with self.assertRaisesRegex(ProtocolError, "timed out"):
            assembler.feed(records[1], now=12.0)

    def test_incompatible_sample_rate_is_rejected(self):
        invalid = START_META.pack(48_000, CHANNELS, PCM16LE, 16_000)
        with self.assertRaisesRegex(ProtocolError, "16 kHz"):
            CaptureAssembler().feed(encode_record(START, CAPTURE_ID, 0, invalid), now=1.0)

    def test_wraps_valid_length_pcm_fixture_as_pcm_wav(self):
        pcm, _ = protocol_fixture()
        payload = pcm_to_wav(pcm)
        with wave.open(BytesIO(payload), "rb") as source:
            self.assertEqual(source.getnchannels(), 1)
            self.assertEqual(source.getframerate(), 16_000)
            self.assertEqual(source.getsampwidth(), 2)
            self.assertEqual(source.getnframes(), 16_000)


if __name__ == "__main__":
    unittest.main()
